/// * The CPU must support the `pclmulqdq`, `ssse3`, `vpclmulqdq`, `aes`, `vaes`, `avx` and `avx2` target features.
#[allow(unused_imports)]
pub use self::vg_aes_gcm_siv_seal_vaes_vpclmul as vg_aes_gcm_siv_seal_vaes_vpclmul_avx512;

